frappe.web_form.after_load = () => {
    // Hide footer
    $("footer").hide();

    // Hide Powered By line
    $(".footer-bottom-line").hide();

    // Prevent browser/Google auto-translate for name fields
    ["customer_name", "first_name", "last_name"].forEach(function(fieldname) {

        let field = frappe.web_form.fields_dict[fieldname];

        if (field && field.$input) {
            field.$input.attr("translate", "no");
            field.$input.attr("autocomplete", "off");
            field.$input.addClass("notranslate");
        }

        if (field && field.$wrapper) {
            field.$wrapper.attr("translate", "no");
            field.$wrapper.addClass("notranslate");
        }
    });

    let dp = frappe.web_form.fields_dict.date.datepicker;

    if (dp) {
        dp.update({
            minDate: new Date(),

            onRenderCell(date, cellType) {
                if (
                    cellType === "day" &&
                    date.getDay() === 5
                ) {
                    return {
                        disabled: true
                    };
                }
            }
        });
    }
    // Disable manual typing in Date field
    if (frappe.web_form.fields_dict.date && frappe.web_form.fields_dict.date.$input) {
        frappe.web_form.fields_dict.date.$input
            .attr("readonly", true)
            .css("cursor", "pointer");
    }

    frappe.web_form.set_value("reference_images_json", "");
    
    let upload_html = `
        <div style="margin-top:10px;">
    
            <input
                type="file"
                id="ws_reference_file_input"
                accept="image/*"
                multiple
                style="display:none;"
            >
    
            <button
                type="button"
                id="ws_upload_reference_files"
                style="
                    width:100%;
                    background:#fafafa;
                    border:2px dashed #d5d9e0;
                    border-radius:8px;
                    padding:14px;
                    color:#344054;
                    font-size:15px;
                    font-weight:600;
                    text-align:center;
                    transition:all .2s ease;
                ">
                📎 Add Reference Images
            </button>
    
            <div id="ws_reference_upload_preview"
                style="margin-top:12px; font-size:13px;">
            </div>
    
        </div>
    `;
    
    frappe.web_form.fields_dict.reference_upload_html.$wrapper.html(upload_html);
    
    $("#ws_upload_reference_files").on("click", function () {
        $("#ws_reference_file_input").click();
    });
    
    $("#ws_reference_file_input").on("change", function () {
    
        let files = this.files;
    
        if (!files || !files.length) {
            return;
        }
    
        $("#ws_upload_reference_files")
            .prop("disabled", true)
            .text("Uploading...");
    
        let total_files = files.length;
        let completed = 0;
    
        Array.from(files).forEach(function(file) {
    
            let form_data = new FormData();
    
            form_data.append("file", file);
            form_data.append("is_private", 0);
            form_data.append("folder", "Home/Attachments");
    
            $.ajax({
                url: "/api/method/upload_file",
                type: "POST",
                data: form_data,
                processData: false,
                contentType: false,
                headers: {
                    "X-Frappe-CSRF-Token": frappe.csrf_token
                },
    
                success: function(r) {
    
                    let file_doc = r.message;
    
                    let existing = frappe.web_form.get_value(
                        "reference_images_json"
                    );
    
                    let uploaded_files = [];
    
                    if (existing) {
                        try {
                            uploaded_files = JSON.parse(existing);
                        }
                        catch (e) {
                            uploaded_files = [];
                        }
                    }
    
                    uploaded_files.push(file_doc.name);
    
                    let raw_json = JSON.stringify(uploaded_files);
    
                    frappe.web_form.set_value(
                        "reference_images_json",
                        raw_json
                    );
    
                    frappe.web_form.doc.reference_images_json = raw_json;
    
                    $("#ws_reference_upload_preview").append(`
                        <div style="
                            padding:8px 10px;
                            margin-bottom:6px;
                            background:#F9FAFB;
                            border:1px solid #E5E7EB;
                            border-radius:8px;
                            color:#344054;
                            font-weight:600;
                        ">
                            ✅ ${file.name}
                        </div>
                    `);
                },
    
                error: function() {
    
                    frappe.msgprint(
                        "Could not upload " + file.name
                    );
                },
    
                complete: function() {
    
                    completed++;
    
                    if (completed >= total_files) {
    
                        $("#ws_upload_reference_files")
                            .prop("disabled", false)
                            .text("📎 Add Reference Images");
                    }
                }
            });
        });
    
        // Allow selecting same file again
        this.value = "";
    });
    // =========================================
    // Country Code UI
    // =========================================
    
    add_country_code_to_phone("mobile_number", "+973");
    add_country_code_to_phone("whatsapp_no", "+973");
};


function add_country_code_to_phone(fieldname, default_code) {

    let field = frappe.web_form.fields_dict[fieldname];

    if (!field || !field.$wrapper) return;

    let $input = field.$wrapper.find("input");

    if (!$input.length) return;

    if (field.$wrapper.find(".ws-country-code").length) return;

    let $select = $(`
        <select class="form-control ws-country-code"
            style="
                width:95px;
                min-width:95px;
                margin-right:8px;
            ">
            <option value="+973">🇧🇭 +973</option>
            <option value="+966">🇸🇦 +966</option>
            <option value="+971">🇦🇪 +971</option>
            <option value="+965">🇰🇼 +965</option>
            <option value="+968">🇴🇲 +968</option>
            <option value="+974">🇶🇦 +974</option>
        </select>
    `);

    $select.val(default_code);

    $input.before($select);

    $input.parent().css({
        display: "flex",
        alignItems: "center",
        gap: "5px"
    });
    
    $select.css({
        width: "120px",
        minWidth: "120px",
        flexShrink: 0
    });
    
    $input.css({
        flex: 1,
        minWidth: 0
    });
}



frappe.web_form.validate = () => {

    let missing = [];

    if (frappe.web_form.get_value("customer_type") === "Company") {

        if (!frappe.web_form.get_value("cr_no")) {
            missing.push("CR No");
        }

        if (!frappe.web_form.get_value("customer_name")) {
            missing.push("Company Name");
        }
    }
    else {

        if (!frappe.web_form.get_value("first_name")) {
            missing.push("First Name");
        }

        if (!frappe.web_form.get_value("last_name")) {
            missing.push("Last Name");
        }
    }

    // =========================================
    // Reference Images Mandatory
    // =========================================

    let reference_images_json = frappe.web_form.get_value(
        "reference_images_json"
    );

    let reference_files = [];

    if (reference_images_json) {
        try {
            reference_files = JSON.parse(reference_images_json);
        }
        catch (e) {
            reference_files = [];
        }
    }

    if (!reference_files.length) {
        missing.push("Reference Images");
    }

    if (!frappe.web_form.get_value("whatsapp_no")) {
        missing.push("Whatsapp No");
    }

    if (!frappe.web_form.get_value("date")) {
        missing.push("Date");
    }

    if (!frappe.web_form.get_value("time")) {
        missing.push("Time");
    }

    if (!frappe.web_form.get_value("city")) {
        missing.push("City");
    }

    if (!frappe.web_form.get_value("subject")) {
        missing.push("Subject");
    }

    // =========================================
    // Phone Validation
    // =========================================

    function get_digits(value) {
        return (value || "").replace(/\D/g, "");
    }

    let whatsapp_digits = get_digits(
        frappe.web_form.get_value("whatsapp_no")
    );

    let mobile_digits = get_digits(
        frappe.web_form.get_value("mobile_number")
    );

    if (
        frappe.web_form.get_value("whatsapp_no") &&
        whatsapp_digits.length < 8
    ) {
        missing.push(
            "WhatsApp No must contain at least 8 digits"
        );
    }

    if (
        frappe.web_form.get_value("mobile_number") &&
        mobile_digits.length < 8
    ) {
        missing.push(
            "Mobile Number must contain at least 8 digits"
        );
    }

    // =========================================
    // Customer Name Must Be English
    // =========================================

    function has_arabic(text) {
        return /[\u0600-\u06FF]/.test(text || "");
    }

    if (frappe.web_form.get_value("customer_type") === "Company") {

        if (has_arabic(frappe.web_form.get_value("customer_name"))) {
            missing.push("Company Name must be in English");
        }

    } else {

        if (
            has_arabic(frappe.web_form.get_value("first_name")) ||
            has_arabic(frappe.web_form.get_value("last_name"))
        ) {
            missing.push("First Name and Last Name must be in English");
        }
    }

    // =========================================
    // Show Errors
    // =========================================

    if (missing.length) {

        frappe.msgprint({
            title: __("Required Fields Missing"),
            indicator: "red",
            message:
                "Please complete the following fields:<br><br>" +
                missing.map(field => "• " + field).join("<br>")
        });

        return false;
    }

    return true;
};

