        map_initialized = true;

        frappe.require("/assets/worldshading/js/service_visit_location_picker.js", function() {
            worldshading.service_visit_location_picker.init({
                api_key: "AIzaSyB-84rmzQI2EwgezHtkjQL-TQMDaK_LcII",
