// =========================================
// Required Field Red Stars
// =========================================

function mark_required(fieldname) {

    let label = $(
        ".frappe-control[data-fieldname='" +
        fieldname +
        "'] .control-label"
    );

    if (
        label.length &&
        !label.find(".ws-required-star").length
    ) {
        label.append(
            '<span class="ws-required-star" style="color:#dc3545;font-weight:bold;"> *</span>'
        );
    }
}

function apply_required_stars() {

    // Always required
    [
        "customer_type",
        "first_name",
        "last_name",
        "whatsapp_no",
        "date",
        "time",
        "city",
        "subject"
    ].forEach(mark_required);

    // Company
    if (frappe.web_form.get_value("customer_type") === "Company") {

        [
            "cr_no",
            "customer_name",
            "first_name",
            "last_name"
        ].forEach(mark_required);
    }

    // Individual
    else if (
        frappe.web_form.get_value("customer_type") === "Individual"
    ) {

        [
            "first_name",
            "last_name"
        ].forEach(mark_required);
    }
}

// Initial load
setTimeout(apply_required_stars, 500);

// Re-run when customer type changes
frappe.web_form.on("customer_type", function () {

    setTimeout(function () {
        apply_required_stars();
    }, 300);

});
